import json; d=json.load(open('.claude/skills/aip/assets/procedure.schema.json'))
for k in ['ExecutionStep','IOItem','Reference','RouterStep']: print(k, json.dumps(d['\$defs'][k]['properties'],indent=0)[:2500])
print(json.dumps({k:v for k,v in d.items() if k!='\$defs'},indent=0)[:3000])"

